const D = { density:.55, scale:1, energy:.6, speed:1, flow:.6, hue:205, x:.5, y:.5, style:'pipes', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU=Math.PI*2, HP=Math.PI/2;
const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const md=(a,n)=>((a%n)+n)%n;
const seed=P.seed|0;
const hh=(a,b)=>{ let s=Math.sin(a*127.1+b*311.7+seed*74.13)*43758.5453; return s-Math.floor(s); };
const fr=i=>{ let s=Math.sin(i*97.3+seed*57.7)*24634.6345; return s-Math.floor(s); };
if (S.lastBeat==null || K.beat<S.lastBeat) S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const style=P.style;
const isPipes=style==='pipes', isNeon=style==='neon', isCircuit=style==='circuit', isStained=style==='stained', isOp=style==='opart';
const av=clp(P.alpha,0,100)/100;
const dens=clp(P.density,0,1), en=clp(P.energy,0,1);
const intn=(K.intensity!=null?K.intensity:.6), sec=K.section||0;
const glow=en*(0.5+0.7*intn);
const flow=clp(P.flow,0,1);
const nColors = isOp?2:3;

// grid fineness (1st poke param): coarse->fine
const cells = 6 + Math.round(dens*24);           // 6..30 tiles across min(w,h)
const ts = u/cells;
const half = ts*0.5;
// pipe/ribbon thickness (2nd poke param)
const swb = ts*0.12*clp(P.scale,0.4,2.4);

// continuous diagonal scroll = real-time motion floor (never re-phases)
const sv = u*0.006*P.speed;
const dirA = 0.5 + fr(3)*1.4;
const ox = K.t*sv*Math.cos(dirA);
const oy = K.t*sv*Math.sin(dirA);

// slow in-place re-roll of edge colors -> the tiling perpetually rewrites (validity preserved: colors live on shared grid edges)
const rr = 0.04*en;
const hueDrift = K.t*3.4 + sec*20;
const ax=P.x*W, ay=P.y*Hh, wl=ts*3.0;

function ecol(kx, ky, salt){
  let base = Math.sin(kx*127.1+ky*311.7+seed*74.13+salt)*43758.5453; base-=Math.floor(base);
  let rate = 0.6 + (Math.sin(kx*57.7+ky*13.3+seed*29.1+salt)*0.5+0.5)*0.9; // 0.6..1.5 desync
  let v = base + K.t*rr*rate; v-=Math.floor(v);
  return Math.floor(v*nColors)%nColors;
}
// vertical edges (W/E) and horizontal edges (N/S) live in independent hash fields -> guaranteed edge-match tiling
const vcol=(X,Y)=>ecol(X*1.7+0.31, Y*2.3+1.11, 11.3);
const hcol=(X,Y)=>ecol(X*2.9+9.71, Y*1.3+4.27, 71.7);

function chue(k, gx, gy){ return md(P.hue + k*(360/nColors) + (gx*3 + gy*4) + hueDrift, 360); }

// ---- background ----
blendMode(BLEND); noStroke();
let bgH,bgS,bgB;
if(isOp){ bgH=md(P.hue,360); bgS=4; bgB=48; }
else if(isCircuit){ bgH=138; bgS=52; bgB=10; }
else if(isStained){ bgH=md(P.hue+200,360); bgS=30; bgB=6; }
else { bgH=md(P.hue+180,360); bgS=48; bgB=8; }   // pipes / neon dark ground
fill(bgH,bgS,bgB,100*av); rect(0,0,W,Hh);
// ambient radial lift so the frame is never near-black (luminance floor)
if(!isOp){
  const gh=md(P.hue+ (isStained?40:120),360);
  for(let r=0;r<3;r++){ fill(gh, isStained?30:44, isStained?18:16, 7*av); ellipse(ax,ay, u*(1.6-r*0.38), u*(1.2-r*0.3)); }
}

const gx0=Math.floor((ox-ts)/ts), gx1=Math.floor((ox+W+ts)/ts);
const gy0=Math.floor((oy-ts)/ts), gy1=Math.floor((oy+Hh+ts)/ts);
const MID=[[0,-half],[half,0],[0,half],[-half,0]]; // N E S W local midpoints
let drawn=0;

strokeCap(ROUND); strokeJoin(ROUND);
if(isNeon) blendMode(ADD); else blendMode(BLEND);

for(let gy=gy0; gy<=gy1; gy++){
  for(let gx=gx0; gx<=gx1; gx++){
    if(drawn++>2600) break;
    const cxp=gx*ts-ox+half, cyp=gy*ts-oy+half;
    const cN=hcol(gx,gy), cE=vcol(gx+1,gy), cS=hcol(gx,gy+1), cW=vcol(gx,gy);
    const cols=[cN,cE,cS,cW];
    const dist=Math.hypot(cxp-ax,cyp-ay);
    const rip=0.5+0.5*Math.sin(dist/wl*TAU - K.t*1.6*P.speed);
    const briBoost=flow*0.45*rip + K.pulse*0.22*en + A.bass*0.5*en;

    push(); translate(cxp,cyp);

    if(isStained){
      // mass-fill: 4 wedges (center->side), colored by that side's edge -> color diamonds span tile borders
      const cor=[[-half,-half],[half,-half],[half,half],[-half,half]]; // TL TR BR BL
      const wed=[[0,1],[1,2],[2,3],[3,0]]; // N:TL-TR, E:TR-BR, S:BR-BL, W:BL-TL
      noStroke();
      for(let e=0;e<4;e++){
        const hcol2=chue(cols[e],gx,gy);
        const b=clp(46+briBoost*26+glow*10, 20, 90);
        fill(hcol2, 66, b, 100*av);
        triangle(0,0, cor[wed[e][0]][0],cor[wed[e][0]][1], cor[wed[e][1]][0],cor[wed[e][1]][1]);
      }
      // dark leading along diagonals + border
      stroke(md(P.hue+200,360), 40, 4, 100*av); strokeWeight(clp(swb*0.7,1,ts*0.14)); noFill();
      for(let c=0;c<4;c++) line(0,0, cor[c][0],cor[c][1]);
      rect(-half,-half,ts,ts);
      // bright bead at center
      noStroke(); fill(chue((cN+cS)&1?cN:cE,gx,gy), 30, clp(70+briBoost*30,0,100), 70*av); circle(0,0, swb*0.9);
      pop(); continue;
    }

    // --- line styles: connect same-colored edges into flowing pipes ---
    noFill();
    const byC={};
    for(let e=0;e<4;e++){ (byC[cols[e]]=byC[cols[e]]||[]).push(e); }
    let hasNode=false;
    for(const kk in byC){
      const arr=byC[kk].slice(); const k=+kk;
      while(arr.length>=2){
        // prefer an opposite pair (straight pipe), else adjacent (elbow)
        let oi=-1,oj=-1;
        for(let i=0;i<arr.length&&oi<0;i++) for(let j=i+1;j<arr.length;j++){ if((arr[i]+2)%4===arr[j]){oi=i;oj=j;break;} }
        let a,b;
        if(oi>=0){ a=arr[oi]; b=arr[oj]; arr.splice(oj,1); arr.splice(oi,1); }
        else { a=arr[0]; b=arr[1]; arr.splice(1,1); arr.splice(0,1); }
        const A0=MID[a], B0=MID[b];
        drawPipe(A0[0],A0[1],B0[0],B0[1], k, gx,gy, briBoost);
      }
      if(arr.length===1){ const M=MID[arr[0]]; drawPipe(M[0],M[1],0,0, k, gx,gy, briBoost); hasNode=true; }
    }
    // small junction node
    if(hasNode || isCircuit){
      noStroke();
      if(isCircuit){ const cu=md(30+(gx*2+gy)*1.1,360); fill(cu,70,clp(66+briBoost*24,0,100),100*av); circle(0,0,swb*1.6); fill(138,52,10,100*av); circle(0,0,swb*0.7); }
      else { fill(chue(cN,gx,gy),24,clp(72+briBoost*26,0,100),60*av); circle(0,0,swb*1.0); }
    }
    pop();
  }
  if(drawn>2600) break;
}

function drawPipe(a1,a2,b1,b2, k, gx,gy, briBoost){
  const hue=chue(k,gx,gy);
  if(isOp){
    // 2-color op-art: color0 -> dark bar, color1 -> light bar, hard edged, high contrast
    const dark = k===0;
    stroke(0,0, dark?6:96, 100*av); strokeWeight(swb*1.8);
    pipeCurve(a1,a2,b1,b2);
    return;
  }
  if(isCircuit){
    const cu=md(28 + k*14 + (gx*2+gy)*1.0,360), b=clp(58+briBoost*30,0,100);
    stroke(md(cu-8,360),64,18,100*av); strokeWeight(swb*2.0); pipeCurve(a1,a2,b1,b2);       // dark trace shadow
    stroke(cu,84,b,100*av); strokeWeight(swb*0.95); pipeCurve(a1,a2,b1,b2);                   // copper core
    stroke(cu,24,clp(b+30,0,100),70*av); strokeWeight(swb*0.3); pipeCurve(a1,a2,b1,b2);       // highlight
    return;
  }
  if(isNeon){
    const b=clp(50+glow*34+briBoost*44,0,100);
    stroke(hue,70,b*0.85,(14+glow*10)*av); strokeWeight(swb*2.9); pipeCurve(a1,a2,b1,b2);      // halo (ADD)
    stroke(hue,38,clp(b+22,0,100),(56+glow*26)*av); strokeWeight(swb*0.9); pipeCurve(a1,a2,b1,b2); // core
    return;
  }
  // pipes (default): glossy tonal multi-hue ribbon on dark ground
  const b=clp(60+briBoost*30,0,100);
  stroke(hue,72,14,100*av); strokeWeight(swb*2.5); pipeCurve(a1,a2,b1,b2);                    // dark casing
  stroke(hue,64,b,100*av); strokeWeight(swb*1.35); pipeCurve(a1,a2,b1,b2);                    // colored body
  stroke(hue,22,clp(b+30,0,100),72*av); strokeWeight(swb*0.36); pipeCurve(a1,a2,b1,b2);       // gloss highlight
}
function pipeCurve(a1,a2,b1,b2){ beginShape(); vertex(a1,a2); quadraticVertex(0,0,b1,b2); endShape(); }

// treble sparkle at random junctions (audio ON TOP, never sole motion)
if(A.treble>0.05){
  blendMode(ADD); noStroke();
  const nsp=Math.floor(14*A.treble);
  for(let i=0;i<nsp;i++){ const sx=fr(i*2.1+Math.floor(K.beat*2))*W, sy=fr(i*3.3+9+Math.floor(K.beat*2))*Hh; fill(md(P.hue+70,360),36,100,52*A.treble*av); circle(sx,sy,u*0.008); }
}
blendMode(BLEND); drawingContext.shadowBlur=0;
